"""Make the CloudFront KeyValueStore hold exactly the pairs in kvs-redirects.json (generated by deploy/aws.py).

    WS_CF_KVS_ARN=arn:aws:cloudfront::<account>:key-value-store/<id> python3 dist/aws/kvs-sync.py [--dry-run]

Puts new and changed keys, deletes keys that are no longer in the file, in UpdateKeys batches. Needs the
AWS CLI v2 (the KeyValueStore API is signed with SigV4A) and a profile allowed to call
cloudfront-keyvaluestore:ListKeys, DescribeKeyValueStore and UpdateKeys. Exits non-zero on any CLI error.
"""

import json
import os
import subprocess
import sys
from pathlib import Path

BATCH = int("{{KVS_UPDATE_BATCH}}")  # CloudFront quota: key-value pairs per UpdateKeys request
BAKED_ARN = "{{KVS_ARN}}"
DATA = Path(__file__).resolve().parent / "kvs-redirects.json"


def aws(*args):
    r = subprocess.run(
        ["aws", "cloudfront-keyvaluestore", *args, "--output", "json"],
        capture_output=True,
        text=True,
    )
    if r.returncode != 0:
        sys.exit(
            f"kvs-sync: aws cloudfront-keyvaluestore {args[0]} failed: {r.stderr.strip()}"
        )
    return json.loads(r.stdout or "{}")


def main():
    arn = os.environ.get("WS_CF_KVS_ARN") or BAKED_ARN
    if not arn.startswith("arn:aws:cloudfront::"):
        sys.exit("kvs-sync: set WS_CF_KVS_ARN to the KeyValueStore ARN")
    desired = {d["key"]: d["value"] for d in json.loads(DATA.read_text())["data"]}
    current, token = {}, None
    while True:
        page = aws(
            "list-keys", "--kvs-arn", arn, *(["--next-token", token] if token else [])
        )
        current.update({i["Key"]: i["Value"] for i in page.get("Items", [])})
        token = page.get("NextToken")
        if not token:
            break
    ops = [
        ("put", {"Key": k, "Value": v})
        for k, v in sorted(desired.items())
        if current.get(k) != v
    ]
    ops += [("delete", {"Key": k}) for k in sorted(current) if k not in desired]
    print(
        f"kvs-sync: {len(desired)} wanted, {len(current)} present, "
        f"{sum(o == 'put' for o, _ in ops)} to put, {sum(o == 'delete' for o, _ in ops)} to delete"
    )
    if "--dry-run" in sys.argv[1:] or not ops:
        return
    etag = aws("describe-key-value-store", "--kvs-arn", arn)["ETag"]
    for i in range(0, len(ops), BATCH):
        chunk = ops[i : i + BATCH]
        puts = [x for o, x in chunk if o == "put"]
        deletes = [x for o, x in chunk if o == "delete"]
        args = ["update-keys", "--kvs-arn", arn, "--if-match", etag]
        args += ["--puts", json.dumps(puts)] if puts else []
        args += ["--deletes", json.dumps(deletes)] if deletes else []
        etag = aws(*args)["ETag"]
    after = aws("describe-key-value-store", "--kvs-arn", arn)
    if after.get("ItemCount") != len(desired):
        sys.exit(
            f"kvs-sync: store holds {after.get('ItemCount')} keys, expected {len(desired)}"
        )
    print(f"kvs-sync: store now holds {after['ItemCount']} keys")


if __name__ == "__main__":
    main()
